    Seed.addObj(s2, { type: 'ball' }, [near(s2.steps[0].pos[gk]), near(s2.steps[1].pos[six])]);
    Formations['11']['4-3-3'].forEach(([lab, x, y, g]) => Seed.addObj(s2, { type: 'player', color: g ? 'orange' : 'blanc', label: g ? 'G' : '', gk: !!g }, [[(1 - x * .8) * L, (1 - y) * W]]));
