      const role = roleM ? roleM[0].replace(/^./, c => c.toUpperCase()).replace(/^Entra[iî]neur$/i, 'Éducateur').replace(/^Coach$/i, 'Éducateur').replace(/^Educateur/i, 'Éducateur') : '';
