;
/* ===== roles.js ===== */
/* Roles: for a responsable only, the app of every kind of member under his own login: a coach (of the chosen categories),
   a volunteer, a referee, a player, a parent. One tap to switch, one tap to come back as responsable; the chosen role stays
   on this device until he changes it. Nothing changes for the others: the roles are kept on this device only. */
var Roles = (() => {
  const { esc, $, $$, toast, modal, confirmBox } = UI;
  const S = () => Store.state;
  const KINDS = { coach: ['🧢', 'Coach', 'L\'appli d\'un éducateur : ses catégories seulement, sans la gestion du club.'],
    benevole: ['🙋', 'Bénévole', 'Ce qu\'utilise un bénévole : les tâches des jours de match et les événements du club.'],
    arbitre: ['🟨', 'Arbitre', 'L\'appli d\'un arbitre du club : ses disponibilités sur les matchs à domicile et ses désignations.'],
    joueur: ['⚽', 'Joueur', 'La vraie page d\'un joueur (avec son code) : convocations, causerie, temps de jeu. Rien sur les autres.'],
    parent: ['👨‍👩‍👧', 'Parent', 'La vraie page d\'un parent : matchs de l\'enfant, convocation, covoiturage, bénévoles.'] };
  const KEY = () => Auth.PREVIEW + '-list';
  const teamName = id => (Store.get('teams', id) || {}).name || '';
  const firstPlayer = teamId => Store.playersOf(teamId).sort(Store.byName)[0];
  function defaults() {
    const u = Auth.current() || {}, t0 = (u.teamIds || []).filter(id => Store.get('teams', id))[0] || (S().teams[0] || {}).id || '';
    const p0 = t0 && firstPlayer(t0);
    return [{ id: 'coach', kind: 'coach', teamIds: t0 ? [t0] : [] }, { id: 'benevole', kind: 'benevole' }, { id: 'arbitre', kind: 'arbitre' },
      { id: 'joueur', kind: 'joueur', teamId: t0, playerId: p0 ? p0.id : '' }, { id: 'parent', kind: 'parent', teamId: t0, playerId: p0 ? p0.id : '' }];
  }
  function list() { try { const l = JSON.parse(localStorage.getItem(KEY())); if (Array.isArray(l) && l.length) return l; } catch (e) {} return defaults(); }
  const save = l => { try { localStorage.setItem(KEY(), JSON.stringify(l)); } catch (e) {} };
  function label(r) {
    const [ic, name] = KINDS[r.kind] || ['', r.kind];
    if (r.kind === 'coach') return `${ic} ${name} · ${(r.teamIds || []).map(teamName).filter(Boolean).join(', ') || 'choisir les catégories'}`;
    if (r.kind === 'joueur' || r.kind === 'parent') { const p = Store.get('players', r.playerId); return `${ic} ${name} · ${p ? Store.shortName(p) : 'choisir'}${r.teamId ? ' (' + teamName(r.teamId) + ')' : ''}`; }
    return `${ic} ${name}`;
  }
  const active = () => { const p = Auth.preview(); return p ? p.id || p.role : 'admin'; };

  function go(r) {
    if (!r) { Auth.stopPreview(); return; }
    if (r.kind === 'coach') { if (!(r.teamIds || []).length) return edit(r); return Auth.startPreview(r.teamIds, 'coach', { id: r.id, label: label(r) }); }
    if (r.kind === 'benevole' || r.kind === 'arbitre') return Auth.startPreview([], r.kind, { id: r.id, label: label(r) });
    // a player or a parent: their real page, full screen (the code of the chosen player)
    if (!r.playerId) return edit(r);
    Auth.viewPage(r.kind, r.teamId, r.playerId);
  }

  function open() {
    if (!Auth.realAdmin()) return;
    const l = list(), on = active();
    const close = modal({ title: '🔀 Mes rôles', noFocus: true, body: `<p class="muted small">Tu passes d'un rôle à l'autre avec ton code : tu vois l'appli exactement comme lui. Rien ne change pour les autres.</p>
      <div class="list">
        <div class="list-item ${on === 'admin' ? 'on' : ''}"><button class="li-main role-go" data-go="admin"><b>🏛️ Responsable du club</b><span class="muted small">Tout le club et sa gestion${on === 'admin' ? ' · <b>rôle actuel</b>' : ''}</span></button></div>
        ${l.map(r => `<div class="list-item ${on === r.id ? 'on' : ''}"><button class="li-main role-go" data-go="${esc(r.id)}"><b>${esc(label(r))}</b><span class="muted small">${esc((KINDS[r.kind] || [])[2] || '')}${on === r.id ? ' · <b>rôle actuel</b>' : ''}</span></button>
          <button class="icon-btn" data-ed="${esc(r.id)}" aria-label="Modifier">${I.edit}</button></div>`).join('')}
      </div>
      <button type="button" class="btn soft wide" data-add>${I.plus}<span>Ajouter un rôle (ex. coach d'une autre catégorie)</span></button>`,
      onOpen: r => {
        $$('[data-go]', r).forEach(b => b.onclick = () => { close(); const id = b.dataset.go; setTimeout(() => go(id === 'admin' ? null : list().find(x => x.id === id)), 60); });
        $$('[data-ed]', r).forEach(b => b.onclick = () => { close(); setTimeout(() => edit(list().find(x => x.id === b.dataset.ed)), 60); });
        $('[data-add]', r).onclick = () => { close(); setTimeout(() => edit({ id: Store.uid(), kind: 'coach', teamIds: [], isNew: true }), 60); };
      } });
  }

  function edit(r) {
    if (!r) return;
    let kind = r.kind, teamIds = [...(r.teamIds || [])], teamId = r.teamId || (S().teams[0] || {}).id || '', playerId = r.playerId || '';
    const teams = S().teams;
    const body = () => `<div class="chips">${Object.entries(KINDS).map(([k, [ic, l]]) => `<button type="button" class="chip ${k === kind ? 'on' : ''}" data-k="${k}">${ic} ${l}</button>`).join('')}</div>
      <p class="muted small">${KINDS[kind][2]}</p>
      ${kind === 'coach' ? `<div class="lbl">Ses catégories</div><div class="chips">${teams.map(t => `<button type="button" class="chip ${teamIds.includes(t.id) ? 'on' : ''}" data-t="${t.id}">${esc(t.name)}</button>`).join('')}</div>` : ''}
      ${kind === 'joueur' || kind === 'parent' ? `<label class="fld"><span>Catégorie</span><select id="rlTeam">${teams.map(t => `<option value="${t.id}" ${t.id === teamId ? 'selected' : ''}>${esc(t.name)}</option>`).join('')}</select></label>
        <label class="fld"><span>${kind === 'parent' ? 'L\'enfant' : 'Le joueur'}</span><select id="rlPl">${Store.playersOf(teamId).sort(Store.byName).map(p => `<option value="${p.id}" ${p.id === playerId ? 'selected' : ''}>${esc(Store.fullName(p))}</option>`).join('') || '<option value="">Aucun joueur</option>'}</select></label>` : ''}`;
    const close = modal({ title: r.isNew ? 'Ajouter un rôle' : 'Modifier le rôle', noFocus: true, body: `<div id="rlBody">${body()}</div>`,
      onOpen: m => {
        const box = $('#rlBody', m), redraw = () => { box.innerHTML = body(); bind(); };
        const bind = () => { const ts = $('#rlTeam', m); if (ts) ts.onchange = e => { teamId = e.target.value; playerId = (firstPlayer(teamId) || {}).id || ''; redraw(); };
          const ps = $('#rlPl', m); if (ps) ps.onchange = e => { playerId = e.target.value; }; };
        box.onclick = e => { const k = e.target.closest('[data-k]'); if (k) { kind = k.dataset.k; if (!playerId) playerId = (firstPlayer(teamId) || {}).id || ''; return redraw(); }
          const t = e.target.closest('[data-t]'); if (t) { teamIds = teamIds.includes(t.dataset.t) ? teamIds.filter(x => x !== t.dataset.t) : [...teamIds, t.dataset.t]; t.classList.toggle('on'); } };
        bind();
      },
      actions: [...(r.isNew ? [] : [{ label: 'Supprimer', kind: 'danger', onClick: () => { save(list().filter(x => x.id !== r.id)); if (active() === r.id) Auth.stopPreview(); toast('Rôle supprimé'); } }]),
        { label: 'Annuler' }, { label: 'Enregistrer et y passer', kind: 'primary', onClick: () => {
          if (kind === 'coach' && !teamIds.length) { toast('Choisis au moins une catégorie', 'err'); return false; }
          if ((kind === 'joueur' || kind === 'parent') && !playerId) { toast('Choisis le joueur', 'err'); return false; }
          const n = { id: r.id, kind, teamIds: kind === 'coach' ? teamIds : undefined, teamId: kind === 'joueur' || kind === 'parent' ? teamId : undefined, playerId: kind === 'joueur' || kind === 'parent' ? playerId : undefined };
          const l = list(), i = l.findIndex(x => x.id === r.id); if (i < 0) l.push(n); else l[i] = n; save(l);
          setTimeout(() => go(n), 60);
        } }] });
  }
  return { open, list, label, KINDS };
})();

;
/* ===== gestion.js ===== */
/* Gestion: the page of the responsable to run the club. What needs to be done in the next two weeks, then every tool
   of the club in one place (people, organisation, sport, communication, data), and « Mes rôles » to switch to the app of a
   coach, a volunteer, a referee, a player or a parent. Only for the responsables. */
var Gestion = (() => {
  const { esc } = UI;
  const S = () => Store.state;
  const pl = (n, w, ws) => `${n} ${n > 1 ? (ws || w + 's') : w}`;
  const addDays = n => { const x = new Date(); x.setDate(x.getDate() + n); return x.toISOString().slice(0, 10); };

  function todo() {
    const now = UI.today(), soon = addDays(14), next = S().matches.filter(m => !m.played && m.date >= now && m.date <= soon);
    const noRef = next.filter(m => m.home && !Store.isFriendly(m) && !m.refId);
    // volunteers: places still free on the tasks of the coming matches
    const tasks = Vol.tasks().filter(t => t.on !== false);
    const volFree = next.reduce((a, m) => a + tasks.filter(t => t.when === 'all' || (t.when === 'home' && m.home) || (t.when === 'away' && !m.home))
      .reduce((b, t) => b + Math.max(0, (+t.need || 1) - (((m.vol || {})[t.key]) || []).length), 0), 0);
    const noCoach = S().teams.filter(t => !Store.staffOf(t.id).length);
    const noScore = S().matches.filter(m => !m.played && !m.exempt && m.date < now && m.date >= People.seasonFrom());
    const noConv = next.filter(m => m.date <= addDays(4) && !(m.convoked || []).length);
    return [
      noRef.length && ['🟨', `${pl(noRef.length, 'match officiel', 'matchs officiels')} à domicile sans arbitre du club`, '#/arbitres'],
      volFree && ['🙋', `${pl(volFree, 'place')} de bénévole à prendre (2 semaines)`, '#/benevoles'],
      noConv.length && ['📋', `${pl(noConv.length, 'match', 'matchs')} dans 4 jours sans convocation`, '#/matchs'],
      noCoach.length && ['🧢', `${pl(noCoach.length, 'catégorie')} sans éducateur : ${noCoach.slice(0, 5).map(t => t.name).join(', ')}`, '#/encadrement'],
      noScore.length && ['⚽', `${pl(noScore.length, 'match', 'matchs')} passé${noScore.length > 1 ? 's' : ''} sans score`, '#/resultats'],
    ].filter(Boolean);
  }

  function page(root) {
    if (!Auth.isAdmin()) { location.hash = '#/'; return; }
    const t = todo(), nRef = Refs.refs().length;
    const tile = (href, ic, label, sub, act) => `<${act ? `button data-g="${act}"` : `a href="${href}"`} class="g-tile"><span class="g-ic">${ic}</span><span><b>${esc(label)}</b>${sub ? `<span class="muted small">${esc(sub)}</span>` : ''}</span></${act ? 'button' : 'a'}>`;
    const group = (title, tiles) => `<h2 class="section">${title}</h2><div class="g-grid">${tiles.join('')}</div>`;
    root.innerHTML = `<header class="page-head"><div><h1>🏛️ Gestion du club</h1><p class="sub">${esc(S().club.name || 'Le club')} · ${pl(S().teams.length, 'catégorie')} · ${pl(S().players.length, 'joueur')} · ${pl(S().staff.length, 'dirigeant')}</p></div>
      <div class="head-actions"><button class="btn primary" data-g="roles">🔀<span>Mes rôles</span></button></div></header>
      <section class="card"><h2>À faire</h2>${t.length ? `<div class="list">${t.map(([ic, txt, href]) => `<a class="list-item" href="${href}"><span class="li-main"><b>${ic} ${esc(txt)}</b></span>${I.back.replace('<svg', '<svg style="transform:rotate(180deg)"')}</a>`).join('')}</div>` : '<p class="muted">Rien d\'urgent : tout est en ordre pour les deux semaines à venir. 👍</p>'}</section>
      ${group('👥 Les personnes', [tile('#/joueurs', '⚽', 'Joueurs', pl(S().players.length, 'licencié')), tile('#/dirigeants', '🧢', 'Dirigeants et comptes', pl(S().staff.length, 'dirigeant')),
        tile('#/codes', '🔑', 'Codes personnels', 'Familles et joueurs : codes, QR, relances'), tile('#/licences', '🧾', 'Licences et cotisations', 'Suivi des dossiers'),
        tile('#/arbitres', '🟨', 'Arbitres', pl(nRef, 'arbitre') + ' du club'), tile('#/benevoles', '🙋', 'Bénévoles', 'Tâches des jours de match')])}
      ${group('🏟️ L\'organisation', [tile('#/equipes', '👕', 'Catégories et équipes', pl(S().teams.length, 'catégorie')), tile('#/encadrement', '📋', 'Qui encadre ?', 'Éducateurs par catégorie'),
        tile('#/planning', '📅', 'Planning des terrains', 'Créneaux et réservations'), tile('#/vestiaires', '🚿', 'Vestiaires', 'Attribution par match'), tile('#/club', '📌', 'Vie du club', 'Événements et signalements')])}
      ${group('⚽ Le sportif', [tile('#/president', '📊', 'Tableau de bord', 'Chiffres de la saison par catégorie'), tile('#/matchs', '🏆', 'Matchs', 'Officiels et amicaux'), tile('#/resultats', '🥇', 'Résultats', 'Toutes les catégories'),
        tile('#/stats', '📈', 'Stats', 'Buts, temps de jeu, présences'), tile('#/bilan', '📘', 'Bilan de saison', 'Par catégorie'), tile('#/exercices', '📚', 'Exercices du club', 'Bibliothèque des coachs')])}
      ${group('📣 La communication', [tile('#/messages', '💬', 'Messagerie', 'Tout le club, catégories, privés'), tile('', '📣', 'Message à tout le club', 'Les dirigeants reçoivent une notification', 'announce')])}
      ${group('🛠️ Les données', [tile('', '📥', 'Importer', 'Joueurs, matchs, dirigeants (photo, PDF, Excel)', 'import'), tile('', '🛟', 'Sauvegardes', 'Automatique chaque lundi, ou à la main', 'backup'),
        tile('#/reglages', '⚙️', 'Réglages du club', 'Couleurs, serveur, notifications, saison')])}`;
    root.onclick = e => {
      const b = e.target.closest('[data-g]'); if (!b) return;
      const g = b.dataset.g;
      if (g === 'roles') return Roles.open();
      if (g === 'backup') return President.backupDialog();
      if (g === 'announce') return announce();
      if (g === 'import') return UI.modal({ title: 'Importer', body: '<p class="muted small">Depuis une photo, une capture d\'écran, un PDF, un fichier Excel / CSV ou un texte copié. Tu vérifies le tableau avant d\'importer : rien n\'est créé en double.</p>',
        actions: [{ label: 'Annuler' }, ...[['players', '👥 Joueurs'], ['matches', '⚽ Matchs'], ['staff', '🧢 Dirigeants']].map(([k, l]) => ({ label: l, onClick: () => { setTimeout(() => Imports.open(k, () => page(root)), 60); } }))] });
    };
  }
  function announce() {
    if (!Cloud.ready()) return UI.toast('Il faut être connecté au serveur du club', 'err');
    UI.modal({ title: '📣 Message à tout le club', body: '<label class="fld"><span>Message</span><textarea id="anTxt" rows="4" maxlength="2000" placeholder="ex : Assemblée générale vendredi 19h au club-house"></textarea></label><p class="muted small">Il part dans « Tout le club » de la messagerie : chaque dirigeant le voit et reçoit une notification.</p>',
      actions: [{ label: 'Annuler' }, { label: 'Envoyer', kind: 'primary', onClick: (c, r) => {
        const txt = r.querySelector('#anTxt').value.trim(); if (!txt) { UI.toast('Écris le message', 'err'); return false; }
        Cloud.post('general', '📣 ' + txt).then(() => UI.toast('Message envoyé à tout le club')).catch(e => UI.toast(e.message || 'Envoi impossible', 'err'));
      } }] });
  }
  return { page, todo };
})();

;
/* ===== season.js ===== */
/* Season: the review of the season of a team (results, scorers, playing time, attendance, progression, injuries),
   a word of the coach, a PDF to hand to the club or the parents, and the full backup of the season before starting the next one. */
var Season = (() => {
  const { esc, $, toast } = UI;
  const S = () => Store.state;
  const res = m => m.gf > m.ga ? 'V' : m.gf < m.ga ? 'D' : 'N';

  function data(t) {
    const from = People.seasonFrom(), now = UI.today();
    const ms = S().matches.filter(m => m.teamId === t.id && m.played && !m.exempt && m.date >= from && Store.kindOk(m)).sort((a, b) => a.date.localeCompare(b.date));
    const trs = S().trainings.filter(x => !x.model && x.teamId === t.id && x.date >= from && x.date <= now);
    const r = { V: 0, N: 0, D: 0 }; ms.forEach(m => r[res(m)]++);
    const gf = ms.reduce((a, m) => a + (+m.gf || 0), 0), ga = ms.reduce((a, m) => a + (+m.ga || 0), 0);
    const players = (Store.playersOf(t.id).length ? Store.playersOf(t.id) : Store.rosterOf(t.id)).map(p => {
      const mp = ms.filter(m => +((m.minutes || {})[p.id]) > 0 || (m.convoked || []).includes(p.id) && (m.minutes || {})[p.id] == null);
      const minutes = ms.reduce((a, m) => a + (+((m.minutes || {})[p.id]) || 0), 0);
      const g = ms.reduce((a, m) => a + (((m.stats || {})[p.id] || {}).g || 0), 0), as = ms.reduce((a, m) => a + (((m.stats || {})[p.id] || {}).a || 0), 0);
      const att = People.attendance(p, t.id), ev = Progress.evals(p).filter(e => e.date >= from), gl = ev.length ? Progress.global(ev[ev.length - 1]) : null;
      const inj = (p.unavail || []).filter(u => u.kind === 'injury' && (u.to || now) >= from).reduce((a, u) => a + Math.max(0, Math.round((new Date((u.to && u.to < now ? u.to : now) + 'T12:00') - new Date((u.from > from ? u.from : from) + 'T12:00')) / 864e5)), 0);
      return { p, mp: mp.length, minutes, g, a: as, att: att.pct, evalG: gl, evalN: ev.length, inj };
    }).sort((a, b) => b.minutes - a.minutes || Store.byName(a.p, b.p));
    return { ms, trs, r, gf, ga, players, trMin: trs.reduce((a, x) => a + (x.exercises || []).reduce((b, e) => b + (+e.duration || 0), 0), 0) };
  }

  function page(root, teamId) {
    const teams = Auth.teams(), t = Store.get('teams', teamId) || Store.get('teams', S().ui.teamId) || teams[0];
    if (!t) { root.innerHTML = '<div class="empty"><p>Crée d\'abord une équipe.</p></div>'; return; }
    const d = data(t), season = People.seasonLabel(), note = ((t.seasonNotes || {})[season]) || '';
    const top = k => d.players.filter(x => x[k] > 0).sort((a, b) => b[k] - a[k]).slice(0, 5);
    root.innerHTML = `<header class="page-head"><div><h1>🏆 Bilan de saison</h1><p class="sub">${esc(t.name)} · ${esc(season)} · ${Store.matchKind() === 'ami' ? 'matchs amicaux' : 'matchs officiels'}</p></div>
      <div class="head-actions"><a class="btn" href="#/stats">${I.back}<span>Statistiques</span></a><button class="btn" data-ss="save">${I.download}<span>Sauvegarder la saison</span></button><button class="btn primary" data-ss="pdf">${I.pdf}<span>Bilan PDF</span></button></div></header>
      <label class="fld inline"><span>Équipe</span><select id="ssTeam">${teams.map(x => `<option value="${x.id}" ${x.id === t.id ? 'selected' : ''}>${esc(Store.teamLabel(x))}</option>`).join('')}</select></label>
      ${UI.kindSeg()}
      <div class="tiles"><div class="tile"><b>${d.ms.length}</b><span>Matchs</span></div><div class="tile v"><b>${d.r.V}</b><span>Victoires</span></div><div class="tile n"><b>${d.r.N}</b><span>Nuls</span></div><div class="tile d"><b>${d.r.D}</b><span>Défaites</span></div>
        <div class="tile"><b>${d.gf} – ${d.ga}</b><span>Buts pour – contre</span></div><div class="tile"><b>${d.trs.length}</b><span>Séances (${Math.round(d.trMin / 60)} h)</span></div></div>
      <div class="cards2">
        <section class="card"><h2>⚽ Buteurs</h2>${top('g').map((x, i) => `<p class="ss-row"><span>${i + 1}. ${esc(Store.fullName(x.p))}</span><b>${x.g}</b></p>`).join('') || '<p class="muted">—</p>'}</section>
        <section class="card"><h2>🅿️ Passeurs</h2>${top('a').map((x, i) => `<p class="ss-row"><span>${i + 1}. ${esc(Store.fullName(x.p))}</span><b>${x.a}</b></p>`).join('') || '<p class="muted">—</p>'}</section>
      </div>
      <section class="card"><h2>👥 Les joueurs</h2><div class="ss-table"><table><thead><tr><th>Joueur</th><th>Matchs</th><th>Minutes</th><th>Buts</th><th>Passes</th><th>Présence</th><th>Éval.</th><th>Blessé</th></tr></thead>
        <tbody>${d.players.map(x => `<tr><td><a href="#/joueur/${x.p.id}">${esc(Store.fullName(x.p))}</a></td><td>${x.mp}</td><td>${x.minutes}'</td><td>${x.g || ''}</td><td>${x.a || ''}</td><td>${x.att == null ? '–' : x.att + ' %'}</td><td>${x.evalG == null ? '–' : x.evalG.toFixed(1).replace('.', ',')}</td><td>${x.inj ? x.inj + ' j' : ''}</td></tr>`).join('')}</tbody></table></div></section>
      <section class="card"><h2>📋 Les résultats</h2><div class="ss-results">${d.ms.map(m => `<a href="#/match/${m.id}" class="res-${res(m)}"><span>${esc(UI.fmtDate(m.date, { day: 'numeric', month: 'short' }))}</span><span>${m.home ? 'contre' : 'chez'} ${esc(m.opponent || '?')}</span><b>${m.gf} – ${m.ga}</b></a>`).join('') || '<p class="muted">Pas encore de match joué.</p>'}</div></section>
      <section class="card"><h2>🗣️ Le mot du coach</h2><textarea id="ssNote" rows="4" placeholder="Ce qu'on retient de la saison, les progrès, les objectifs pour la suivante (apparaît dans le PDF)">${esc(note)}</textarea></section>`;
    $('#ssTeam', root).onchange = e => { location.hash = '#/bilan/' + e.target.value; };
    $('#ssNote', root).oninput = e => { t.seasonNotes = Object.assign({}, t.seasonNotes || {}, { [season]: e.target.value }); clearTimeout(page.t); page.t = setTimeout(() => Store.upsert('teams', t), 600); };
    root.onclick = async e => { const b = e.target.closest('[data-ss]'); if (!b) return;
      if (b.dataset.ss === 'pdf') return pdf(t);
      if (b.dataset.ss === 'save') { try { const r = await Exporter.json(Store.exportAll(), `raincy-saison-${season}`); if (r === 'downloaded') toast('Sauvegarde enregistrée dans Téléchargements'); } catch (err) { toast('Sauvegarde impossible', 'err'); } } };
  }

  async function pdf(t) {
    const b = UI.busy('Création du bilan…');
    try {
      const d = data(t), season = People.seasonLabel(), P = Exporter.pdfDoc(S().club), note = ((t.seasonNotes || {})[season]) || '';
      P.header('Bilan de saison', `${t.name} · ${season}`); P.h2(`${t.name} · saison ${season}`);
      P.facts([['Matchs', String(d.ms.length)], ['V / N / D', `${d.r.V} / ${d.r.N} / ${d.r.D}`], ['Buts', `${d.gf} pour · ${d.ga} contre`], ['Séances', `${d.trs.length} (${Math.round(d.trMin / 60)} h)`]]);
      if (note) { P.label('Le mot du coach'); P.para(note, 11.5); }
      const top = k => d.players.filter(x => x[k] > 0).sort((a, c) => c[k] - a[k]).slice(0, 5);
      if (top('g').length) { P.label('Meilleurs buteurs'); P.table(['Joueur', 'Buts'], top('g').map(x => [Store.fullName(x.p), String(x.g)]), [.8, .2]); }
      if (top('a').length) { P.label('Meilleurs passeurs'); P.table(['Joueur', 'Passes'], top('a').map(x => [Store.fullName(x.p), String(x.a)]), [.8, .2]); }
      P.label('Les joueurs'); P.table(['Joueur', 'Matchs', 'Min.', 'Buts', 'Passes', 'Présence', 'Éval.'], d.players.map(x => [Store.fullName(x.p), String(x.mp), String(x.minutes), String(x.g || ''), String(x.a || ''), x.att == null ? '-' : x.att + ' %', x.evalG == null ? '-' : x.evalG.toFixed(1)]), [.34, .1, .1, .1, .1, .13, .13]);
      if (d.ms.length) { P.label('Les résultats'); P.table(['Date', 'Adversaire', 'Score', ''], d.ms.map(m => [UI.fmtDate(m.date), `${m.home ? 'contre' : 'chez'} ${m.opponent || '?'}`, `${m.gf} - ${m.ga}`, { V: 'Victoire', N: 'Nul', D: 'Défaite' }[res(m)]]), [.25, .45, .15, .15]); }
      const r = await Exporter.deliver(P.blob(), `bilan-${String(t.name).replace(/[^\wÀ-ÿ-]+/g, '-')}-${season}.pdf`);
      if (r === 'downloaded') toast('Bilan enregistré dans Téléchargements');
    } catch (e) { console.error(e); toast('Bilan impossible : ' + (e.message || e), 'err'); } finally { b.done(); }
  }
  /* ---------- detailed statistics (Stats page): form, points, home / away, clean sheets, goals by period (live match) ---------- */
  function advanced(t) {
    const from = People.seasonFrom(), ms = S().matches.filter(m => m.teamId === t.id && m.played && !m.exempt && m.date >= from && Store.kindOk(m)).sort((a, b) => a.date.localeCompare(b.date));
    if (!ms.length) return '';
    const pts = m => ({ V: 3, N: 1, D: 0 })[res(m)], rec = l => { const r = { V: 0, N: 0, D: 0, gf: 0, ga: 0 }; l.forEach(m => { r[res(m)]++; r.gf += +m.gf || 0; r.ga += +m.ga || 0; }); return r; };
    const home = rec(ms.filter(m => m.home)), away = rec(ms.filter(m => !m.home)), total = ms.reduce((a, m) => a + pts(m), 0);
    const cs = ms.filter(m => !+m.ga).length, scored = ms.filter(m => +m.gf > 0).length, form = ms.slice(-5);
    const big = ms.slice().sort((a, b) => (b.gf - b.ga) - (a.gf - a.ga))[0], bad = ms.slice().sort((a, b) => (a.gf - a.ga) - (b.gf - b.ga))[0];
    // goals by period of 15 min, from the matches followed live
    const lives = ms.filter(m => m.live && (m.live.events || []).length), bands = {}, bandOf = min => { const n = parseInt(min, 10) || 0; const half = (m => m.live.halfLen)(lives[0] || { live: { halfLen: 45 } }); return Math.min(Math.floor((n - 1) / 15), Math.ceil(half * 2 / 15) - 1); };
    lives.forEach(m => m.live.events.forEach(e => { if (e.type !== 'goal' && e.type !== 'against') return; const b = bandOf(e.min); bands[b] = bands[b] || { f: 0, a: 0 }; bands[b][e.type === 'goal' ? 'f' : 'a']++; }));
    const firsts = lives.map(m => { const g = m.live.events.filter(e => e.type === 'goal' || e.type === 'against').sort((a, b) => a.wall - b.wall)[0]; return g ? { us: g.type === 'goal', r: res(m) } : null; }).filter(Boolean);
    const whenFirst = r => { const l = firsts.filter(x => x.us === r); return l.length ? `${l.filter(x => x.r === 'V').length} V · ${l.filter(x => x.r === 'N').length} N · ${l.filter(x => x.r === 'D').length} D` : '–'; };
    const maxB = Math.max(1, ...Object.values(bands).map(b => Math.max(b.f, b.a)));
    return `<section class="card adv"><h2>📊 Statistiques avancées</h2>
      <div class="adv-form">Forme : ${form.map(m => `<a href="#/match/${m.id}" class="f-${res(m)}" title="${esc(m.opponent || '')} ${m.gf}-${m.ga}">${res(m)}</a>`).join('')}<span class="muted small">${total} pts en ${ms.length} matchs · ${(total / ms.length).toFixed(2).replace('.', ',')} par match</span></div>
      <div class="adv-grid"><div><h3>🏠 À domicile</h3><p>${home.V} V · ${home.N} N · ${home.D} D</p><p class="muted small">${home.gf} – ${home.ga}</p></div>
        <div><h3>🚌 À l'extérieur</h3><p>${away.V} V · ${away.N} N · ${away.D} D</p><p class="muted small">${away.gf} – ${away.ga}</p></div>
        <div><h3>🧤 Sans encaisser</h3><p>${cs} match${cs > 1 ? 's' : ''}</p><p class="muted small">${Math.round(cs / ms.length * 100)} % des matchs</p></div>
        <div><h3>⚽ A marqué</h3><p>${scored} match${scored > 1 ? 's' : ''} sur ${ms.length}</p><p class="muted small">${(ms.reduce((a, m) => a + (+m.gf || 0), 0) / ms.length).toFixed(1).replace('.', ',')} but${ms.length ? 's' : ''} par match</p></div>
        ${big ? `<div><h3>🏆 Plus large victoire</h3><p>${big.gf} – ${big.ga}</p><p class="muted small">${big.home ? 'contre' : 'chez'} ${esc(big.opponent || '?')}</p></div>` : ''}
        ${bad && bad.gf < bad.ga ? `<div><h3>📉 Plus lourde défaite</h3><p>${bad.gf} – ${bad.ga}</p><p class="muted small">${bad.home ? 'contre' : 'chez'} ${esc(bad.opponent || '?')}</p></div>` : ''}</div>
      ${lives.length ? `<h3>⏱️ Buts par période de 15 min (${lives.length} match${lives.length > 1 ? 's' : ''} suivi${lives.length > 1 ? 's' : ''} en direct)</h3>
        <div class="adv-bands">${Object.keys(bands).map(Number).sort((a, b) => a - b).map(b => `<div><span>${b * 15 + 1}-${(b + 1) * 15}'</span><i class="f" style="width:${bands[b].f / maxB * 100}%">${bands[b].f || ''}</i><i class="a" style="width:${bands[b].a / maxB * 100}%">${bands[b].a || ''}</i></div>`).join('')}</div>
        <p class="muted small">En vert nos buts, en rouge les buts encaissés. Quand on marque le premier : ${whenFirst(true)} · quand on encaisse le premier : ${whenFirst(false)}.</p>`
        : '<p class="muted small">Suis tes matchs en direct (📱 sur la page du match) pour voir les buts par période et les résultats selon qui marque le premier.</p>'}</section>`;
  }
  /* ---------- the detailed stats of a match (shots, key passes, interceptions, crosses, corners, cards, saves) ---------- */
  const DET = [['g', '⚽', 'Buts'], ['a', '🅿️', 'Passes déc.'], ['sc', '🎯', 'Tirs cadrés'], ['snc', '↗️', 'Non cadrés'], ['d', '🔑', 'Passes clés'], ['iv', '✋', 'Interceptions'],
    ['cr', '📐', 'Centres'], ['co', '🚩', 'Corners'], ['yc', '🟨', 'Jaunes'], ['rc', '🟥', 'Rouges'], ['sv', '🧤', 'Arrêts']];
  function detailCard(m) {
    const det = m.detail || {}, st = m.stats || {}, ids = [...new Set([...Object.keys(det), ...Object.keys(st)])].filter(id => Store.get('players', id));
    if (!ids.length || !Object.keys(det).length) return '';
    const v = (id, k) => k === 'g' || k === 'a' ? ((st[id] || {})[k] || 0) : ((det[id] || {})[k] || 0);
    const cols = DET.filter(([k]) => ids.some(id => v(id, k)));
    const rows = ids.map(id => ({ p: Store.get('players', id), id })).sort((a, b) => cols.reduce((s, [k]) => s + v(b.id, k), 0) - cols.reduce((s, [k]) => s + v(a.id, k), 0));
    return `<section class="card"><h2>📊 Stats détaillées</h2><div class="ss-table"><table><thead><tr><th>Joueur</th>${cols.map(([, ic, l]) => `<th title="${esc(l)}">${ic}<br><small>${esc(l)}</small></th>`).join('')}</tr></thead>
      <tbody>${rows.map(r => `<tr><td><a href="#/joueur/${r.id}">${esc(Store.shortName(r.p))}</a></td>${cols.map(([k]) => `<td>${v(r.id, k) || ''}</td>`).join('')}</tr>`).join('')}</tbody>
      <tfoot><tr><td><b>Équipe</b></td>${cols.map(([k]) => `<td><b>${ids.reduce((s, id) => s + v(id, k), 0)}</b></td>`).join('')}</tr></tfoot></table></div></section>`;
  }
  // a player's detailed stats over the season (player page)
  function playerDetail(p) {
    const from = People.seasonFrom(), ms = S().matches.filter(m => m.played && m.date >= from && Store.kindOk(m) && ((m.detail || {})[p.id] || ((m.stats || {})[p.id])));
    if (!ms.some(m => (m.detail || {})[p.id])) return '';
    const sum = k => ms.reduce((s, m) => s + (k === 'g' || k === 'a' ? (((m.stats || {})[p.id] || {})[k] || 0) : (((m.detail || {})[p.id] || {})[k] || 0)), 0);
    return `<section class="card"><h2>📊 Ses stats détaillées</h2><div class="tt-cards">${DET.filter(([k]) => sum(k)).map(([k, ic, l]) => `<div><span>${ic} ${esc(l)}</span><b>${sum(k)}</b></div>`).join('')}</div></section>`;
  }

  /* ---------- the league table (championships imported from AssistCoachAI, completed by our results) ---------- */
  function table(t) {
    const L = t.league; if (!L) return null;
    const pts = Object.assign({ win: 3, draw: 1, loss: 0 }, (L.config || {}).points || {}), T = {};
    L.teams.forEach(x => { T[x.id] = { id: x.id, name: x.own ? `${S().club.name} · ${t.name}` : x.name, own: x.own, j: 0, v: 0, n: 0, d: 0, bp: 0, bc: 0, pts: -(x.pen || 0) }; });
    const own = L.teams.find(x => x.own), ours = S().matches.filter(m => m.teamId === t.id && m.played);
    L.fixtures.forEach(f => {
      let hs = f.hs, as = f.as;
      // our own matches: the score typed in the app wins (the league file may be older)
      if (own && (f.h === own.id || f.a === own.id)) { const opp = L.teams.find(x => x.id === (f.h === own.id ? f.a : f.h)); const m = opp && ours.find(x => x.date === f.d && ACImport.sameOpp(x.opponent, opp.name)); if (m) { hs = f.h === own.id ? m.gf : m.ga; as = f.h === own.id ? m.ga : m.gf; } }
      if (hs == null || as == null || !T[f.h] || !T[f.a]) return;
      const H = T[f.h], A = T[f.a]; H.j++; A.j++; H.bp += +hs; H.bc += +as; A.bp += +as; A.bc += +hs;
      if (+hs > +as) { H.v++; A.d++; H.pts += pts.win; A.pts += pts.loss; } else if (+hs < +as) { A.v++; H.d++; A.pts += pts.win; H.pts += pts.loss; } else { H.n++; A.n++; H.pts += pts.draw; A.pts += pts.draw; }
    });
    return Object.values(T).sort((a, b) => b.pts - a.pts || (b.bp - b.bc) - (a.bp - a.bc) || b.bp - a.bp || b.v - a.v || a.name.localeCompare(b.name));
  }
  function leagueCard(t) {
    const rows = table(t); if (!rows) return '';
    const up = +((t.league.config || {}).promotion_slots || 0), down = +((t.league.config || {}).relegation_slots || 0);
    return `<section class="card"><h2>🏆 ${esc(t.league.name)}</h2><div class="ss-table"><table class="lg-table"><thead><tr><th>#</th><th>Équipe</th><th>Pts</th><th>J</th><th>V</th><th>N</th><th>D</th><th>Diff</th></tr></thead>
      <tbody>${rows.map((r, i) => `<tr class="${r.own ? 'own' : ''} ${i < up ? 'up' : ''} ${down && i >= rows.length - down ? 'down' : ''}"><td>${i + 1}</td><td>${esc(r.name)}</td><td><b>${r.pts}</b></td><td>${r.j}</td><td>${r.v}</td><td>${r.n}</td><td>${r.d}</td><td>${r.bp - r.bc > 0 ? '+' : ''}${r.bp - r.bc}</td></tr>`).join('')}</tbody></table></div>
      <p class="muted small">${up ? `En vert : ${up} place${up > 1 ? 's' : ''} de montée. ` : ''}Nos scores saisis dans l'appli sont pris en compte.</p></section>`;
  }
  return { page, pdf, data, advanced, detailCard, playerDetail, table, leagueCard };
})();

